G=[[0,8,8,0,8,8,0],[8,8,8,8,8,8,0],[0,8,8,0,8,0,0],[0,0,8,8,8,0,0],[0]*7,[0]*7,[0]*7]
occ={(r,c) for r,row in enumerate(G) for c,v in enumerate(row) if v}
# all candidate unit-square windows and L triple windows
pieces=[]
for r in range(6):
 for c in range(6):
  cells={(r+i,c+j) for i in range(2) for j in range(2)}
  if cells<=occ: pieces.append((cells,1,(r,c,'S')))
  for miss in [(0,0),(0,1),(1,0),(1,1)]:
   p=cells-{(r+miss[0],c+miss[1])}
   if p<=occ: pieces.append((p,{(0,0):2,(1,0):3,(0,1):4,(1,1):5}[miss],(r,c,miss)))
bycell={p:set() for p in occ}
for p in pieces:
 for cell in p[0]: bycell[cell].add(p)
def rec(rem,chosen):
 if not rem: yield chosen; return
 cell=min(rem,key=lambda x:sum(1 for p in bycell[x] if p[0]<=rem))
 for p in bycell[cell]:
  if p[0]<=rem: yield from rec(rem-p[0],chosen+[p])
sol=list(rec(occ,[]))
len(sol)

